    join(agentCtlPath, "..", "control.env"),
    [
      `WEBMUX_CONTROL_URL='${controlUrl}'`,
      "WEBMUX_CONTROL_TOKEN='test-token'",
      "WEBMUX_WORKTREE_ID='worktree-1'",
      "WEBMUX_BRANCH='feature/test'",
      "",
    ].join("\n"),
  );
}

